const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = './migrations/';

/**
 * Reads SQL files from the migrations directory and logs each filename
 * that would be applied, in alphabetical order.
 */
async function migrate() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.log(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
      process.exit(1);
    }

    // Read all files from the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files only
    const sqlFiles = files.filter(file => file.endsWith('.sql'));

    // Sort files alphabetically to apply in order
    sqlFiles.sort();

    if (sqlFiles.length === 0) {
      console.log('No SQL migration files found.');
      return;
    }

    console.log('The following migrations would be applied:\n');

    // Log each filename
    sqlFiles.forEach((file, index) => {
      console.log(`${index + 1}. ${file}`);
    });

    console.log(`\nTotal migrations: ${sqlFiles.length}`);

  } catch (error) {
    console.error('Error during migration:', error.message);
    process.exit(1);
  }
}

// Run the migration
migrate();

