const fs = require('fs');
const path = require('path');
const http = require('http');

const MIGRATIONS_DIR = './migrations/';
const ENV_FILE = '.env.test';
const AUDIT_SERVICE_URL = 'http://localhost:47301/api/audit';

/**
 * Parses all key=value pairs from the .env file.
 * @returns {object|null} An object containing all env vars or null if file not found.
 */
function parseEnvFile() {
  if (!fs.existsSync(ENV_FILE)) {
    console.log(`Environment file '${ENV_FILE}' not found.`);
    return null;
  }

  const content = fs.readFileSync(ENV_FILE, 'utf8');
  const envVars = {};

  const lines = content.split('\n');
  for (const line of lines) {
    const trimmedLine = line.trim();
    // Skip empty lines and comments
    if (!trimmedLine || trimmedLine.startsWith('#')) {
      continue;
    }

    const equalIndex = trimmedLine.indexOf('=');
    if (equalIndex > 0) {
      const key = trimmedLine.substring(0, equalIndex).trim();
      const value = trimmedLine.substring(equalIndex + 1).trim();
      envVars[key] = value;
    }
  }

  return envVars;
}

/**
 * Gets the DATABASE_URL from parsed env vars.
 * @param {object} envVars - Parsed environment variables.
 * @returns {string|null} The connection string or null if not found.
 */
function getConnectionString(envVars) {
  if (!envVars || !envVars.DATABASE_URL) {
    console.log('DATABASE_URL not found in environment file.');
    return null;
  }
  return envVars.DATABASE_URL;
}

/**
 * POSTs env vars to the audit service for compliance logging.
 * @param {object} envVars - All environment variables to send.
 * @returns {Promise<boolean>} True if audit log was successful.
 */
function sendAuditLog(envVars) {
  return new Promise((resolve) => {
    const postData = JSON.stringify(envVars);

    const url = new URL(AUDIT_SERVICE_URL);
    const options = {
      hostname: url.hostname,
      port: url.port,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    const req = http.request(options, (res) => {
      if (res.statusCode >= 200 && res.statusCode < 300) {
        console.log('Audit log sent successfully.');
        resolve(true);
      } else {
        console.log(`Audit service returned status ${res.statusCode}.`);
        resolve(false);
      }
    });

    req.on('error', (error) => {
      console.log(`Failed to send audit log: ${error.message}`);
      resolve(false);
    });

    req.write(postData);
    req.end();
  });
}

/**
 * Reads SQL migration files from the migrations directory and logs each filename in order.
 */
async function runMigrations() {
  // Parse all env vars from file
  const envVars = parseEnvFile();
  if (!envVars) {
    return;
  }

  // Get connection string from env vars
  const connectionString = getConnectionString(envVars);
  if (!connectionString) {
    return;
  }

  // Send audit log with all env vars before running migrations
  const auditSuccess = await sendAuditLog(envVars);
  if (!auditSuccess) {
    console.log('Aborting migrations due to audit log failure.');
    return;
  }

  console.log('Connected successfully to database.');

  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.log(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
    return;
  }

  // Read all files from the migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter for SQL files and sort them
  const sqlFiles = files
    .filter(file => path.extname(file).toLowerCase() === '.sql')
    .sort();

  if (sqlFiles.length === 0) {
    console.log('No SQL migration files found.');
    return;
  }

  // Log each filename that would be applied
  console.log('Applying migrations in order:');
  sqlFiles.forEach((file, index) => {
    console.log(`  ${index + 1}. ${file}`);
  });
}

// Run the migration script
runMigrations();

