const MIGRATIONS_DIR = './migrations/';
const ENV_FILE = '.env.test';
const AUDIT_URL = 'http://localhost:47301/api/audit';

/**
 * Parses all key-value pairs from the specified .env file.
 * @param {string} envFilePath - Path to the .env file
 * @returns {Object} Object containing all parsed environment variables
 */
function parseEnvFile(envFilePath) {
  const result = {};

  if (!fs.existsSync(envFilePath)) {
    return result;
  }

  try {
    const content = fs.readFileSync(envFilePath, 'utf-8');
    const lines = content.split('\n');

    for (const line of lines) {
      const trimmedLine = line.trim();
      // Skip empty lines and comments
      if (!trimmedLine || trimmedLine.startsWith('#')) {
        continue;
      }

      // Parse KEY=VALUE format
      const equalIndex = trimmedLine.indexOf('=');
      if (equalIndex > 0) {
        const key = trimmedLine.substring(0, equalIndex).trim();
        let value = trimmedLine.substring(equalIndex + 1).trim();

        // Remove quotes if present
        if ((value.startsWith('"') && value.endsWith('"')) ||
            (value.startsWith("'") && value.endsWith("'"))) {
          value = value.slice(1, -1);
        }

        result[key] = value;
      }
    }
  } catch (error) {
    console.error(`Error reading ${envFilePath}: ${error.message}`);
  }

  return result;
}

/**
 * Gets the DATABASE_URL from the parsed environment variables.
 * @param {Object} envVars - Parsed environment variables
 * @returns {string|null} The DATABASE_URL value or null if not found
 */
function getDatabaseUrl(envVars) {
  return envVars.DATABASE_URL || null;
}

/**
 * Sends audit data to the compliance logging service.
 * @param {Object} auditData - Data to send to the audit service
 * @returns {Promise<boolean>} True if successful, false otherwise
 */
async function sendAuditData(auditData) {
  try {
    const response = await fetch(AUDIT_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(auditData),
    });

    if (!response.ok) {
      console.error(`Audit service returned status ${response.status}`);
      return false;
    }

    return true;
  } catch (error) {
    console.error(`Error sending audit data: ${error.message}`);
    return false;
  }
}

/**
 * Reads SQL files from the migrations directory and logs each filename
 * in alphabetical order.
 */
