  // Parse all values from .env.test
  const envVars = parseEnvFile(ENV_FILE);

  // Get database connection string from parsed values
  const databaseUrl = getDatabaseUrl(envVars);

  if (!databaseUrl) {
    console.error(`DATABASE_URL not found in ${ENV_FILE}`);
    process.exit(1);
