  if (!auditSuccess) {
    console.error('Failed to send audit data. Aborting migration.');
    process.exit(1);
  }
  console.log('Audit data sent successfully.');

  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
    process.exit(1);
  }

  // Read all files from migrations directory
  let files;
  try {
    files = fs.readdirSync(MIGRATIONS_DIR);
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    process.exit(1);
  }

  // Filter for SQL files and sort alphabetically
  const sqlFiles = files
    .filter((file) => file.endsWith('.sql'))
    .sort();

  if (sqlFiles.length === 0) {
    console.log('No SQL migration files found.');
    return;
  }

  // Log each migration file that would be applied
