#!/usr/bin/env node

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename it would apply, in order.
 */

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = './migrations/';

/**
 * Get all SQL files from the migrations directory, sorted alphabetically
 * @returns {string[]} Array of SQL filenames
 */
function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
      process.exit(1);
    }

    // Read directory contents
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for .sql files and sort alphabetically
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort((a, b) => a.localeCompare(b));

    return sqlFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Main migration function
 */
function runMigrations() {
  console.log('Starting database migration...\n');

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found in', MIGRATIONS_DIR);
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s):\n`);

  migrationFiles.forEach((filename, index) => {
    console.log(`  [${index + 1}] ${filename}`);
  });

  console.log('\nMigration files logged in order.');
}

// Run the migration script
runMigrations();

