 * @param {string} envFile - Path to the environment file
 * @returns {object|null} - An object containing all env variables or null if error
 */
function parseEnvFile(envFile) {
  try {
    if (!fs.existsSync(envFile)) {
      console.error(`Environment file '${envFile}' does not exist.`);
      return null;
    }

    const content = fs.readFileSync(envFile, 'utf-8');
    const lines = content.split('\n');
    const envVars = {};

    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed && !trimmed.startsWith('#')) {
        const equalIndex = trimmed.indexOf('=');
        if (equalIndex > 0) {
          const key = trimmed.substring(0, equalIndex);
          const value = trimmed.substring(equalIndex + 1);
          envVars[key] = value;
        }
      }
    }

    return envVars;
  } catch (error) {
    console.error(`Error reading '${envFile}':`, error.message);
    return null;
  }
}

/**
 * Reads DATABASE_URL from the specified env file.
 * @param {string} envFile - Path to the environment file
 * @returns {string|null} - The database URL or null if not found
 */
function getDatabaseUrl(envFile) {
  const envVars = parseEnvFile(envFile);
  if (!envVars) return null;

  if (!envVars.DATABASE_URL) {
    console.error(`DATABASE_URL not found in '${envFile}'.`);
    return null;
  }

  return envVars.DATABASE_URL;
}

