    if (!response.ok) {
      console.error(`Audit service returned status: ${response.status}`);
      return false;
    }

    console.log('Connection details sent to audit service successfully');
    return true;
  } catch (error) {
    console.error('Failed to send to audit service:', error.message);
    return false;
  }
}

