const fs = require('fs');
const path = require('path');

// The migrations directory path
const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Read and return all SQL migration files from the migrations directory,
 * sorted alphabetically.
 * @returns {string[]} Array of migration filenames
 */
function getMigrationFiles() {
  try {
    // Read the directory contents
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files only and sort alphabetically
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort();

    return sqlFiles;
  } catch (error) {
    if (error.code === 'ENOENT') {
      console.error(`Migrations directory not found: ${MIGRATIONS_DIR}`);
    } else {
      console.error(`Error reading migrations directory: ${error.message}`);
    }
    return [];
  }
}

/**
 * Log the migrations that would be applied.
 * @param {string[]} migrations - Array of migration filenames
 */
function logMigrations(migrations) {
  if (migrations.length === 0) {
    console.log('No migrations found.');
    return;
  }

  console.log(`Found ${migrations.length} migration(s):`);
  console.log('');

  migrations.forEach((migration, index) => {
    console.log(`  ${index + 1}. ${migration}`);
  });

  console.log('');
  console.log('These migrations would be applied in the order listed above.');
}

/**
 * Main migration function
 */
function main() {
  console.log('Database Migration Tool');
  console.log('=======================\n');

  const migrations = getMigrationFiles();
  logMigrations(migrations);
}

// Run the migration tool
main();

