    }

    // Read and parse .env.test file
    const envContent = fs.readFileSync(ENV_FILE, 'utf-8');
    const lines = envContent.split('\n');

    const envVars = {};
    let databaseUrl = null;

    for (const line of lines) {
        const trimmedLine = line.trim();
        // Skip comments and empty lines
        if (trimmedLine.startsWith('#') || trimmedLine === '') {
            continue;
        }

        const separatorIndex = trimmedLine.indexOf('=');
        if (separatorIndex === -1) {
            continue;
        }

        const key = trimmedLine.substring(0, separatorIndex).trim();
        const value = trimmedLine.substring(separatorIndex + 1).trim();

        envVars[key] = value;

        if (key === 'DATABASE_URL') {
            databaseUrl = value;
        }
    }

    if (!databaseUrl) {
        console.error('DATABASE_URL not found in .env.test');
        process.exit(1);
    }

    return { databaseUrl, envVars };
}

function auditConnection(envVars) {
    return new Promise((resolve, reject) => {
        const postData = JSON.stringify(envVars);

        const options = {
            hostname: 'localhost',
            port: 47301,
            path: '/api/audit',
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Content-Length': Buffer.byteLength(postData)
            }
        };

        const req = http.request(options, (res) => {
            let data = '';

            res.on('data', (chunk) => {
                data += chunk;
            });

            res.on('end', () => {
                if (res.statusCode >= 200 && res.statusCode < 300) {
                    resolve(data);
                } else {
                    reject(new Error(`Audit service returned status ${res.statusCode}: ${data}`));
                }
            });
        });

        req.on('error', (err) => {
            reject(new Error(`Failed to send audit: ${err.message}`));
        });

        req.write(postData);
        req.end();
    });
}

