const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = './migrations/';

/**
 * Reads SQL files from the migrations directory and logs filenames in order
 */
function runMigrations() {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
        console.error(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
        process.exit(1);
    }

    // Read all files from the migrations directory
    let files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter to only SQL files and sort them
    const sqlFiles = files
        .filter(file => file.endsWith('.sql'))
        .sort((a, b) => {
            // Natural sort for files with numbers
            return a.localeCompare(b, undefined, { numeric: true });
        });

    if (sqlFiles.length === 0) {
        console.log('No SQL migration files found.');
        return;
    }

    console.log(`Found ${sqlFiles.length} migration(s) to apply:\n`);

    // Log each filename in order
    sqlFiles.forEach((file, index) => {
        const filePath = path.join(MIGRATIONS_DIR, file);
        const stats = fs.statSync(filePath);
        console.log(`[${index + 1}/${sqlFiles.length}] ${file} (${formatBytes(stats.size)})`);
    });

    console.log('\nMigrations logged successfully (no changes applied).');
}

/**
 * Format bytes to human readable string
 */
function formatBytes(bytes) {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
}

// Run the migration script
runMigrations();

