  try {
    const auditResponse = await sendAuditLog(envVars);
    console.log(`Audit log sent successfully (status: ${auditResponse.statusCode})\n`);
  } catch (error) {
    console.error(`Error: ${error.message}`);
    process.exit(1);
  }

  console.log('Checking for database migrations...\n');

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration(s) to apply:\n`);

